import * as T from '../../vendor/three.module.js';
const pixels={"lka_bark01":{"width":256,"height":256,"rgba":""},"lka_bark04":{"width":128,"height":128,"rgba":""},"lka_hrdwd02":{"width":256,"height":256,"rgba":""},"lka_wall01":{"width":256,"height":256,"rgba":""},"lka_wall06":{"width":256,"height":256,"rgba":""}};
const cache=new Map();
export function kotorTexture(name){if(!cache.has(name)){const s=pixels[name],raw=atob(s.rgba),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)),texture=new T.DataTexture(bytes,s.width,s.height);texture.colorSpace=T.SRGBColorSpace;texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.magFilter=T.LinearFilter;texture.minFilter=T.LinearMipmapLinearFilter;texture.generateMipmaps=true;texture.anisotropy=4;texture.needsUpdate=true;texture.userData.kotorTexture=name;cache.set(name,texture);}return cache.get(name);}
